dtsPropsFor.Button:
/** Визуальный вес. primary — главное действие экрана (оно должно быть одно), secondary — равнозначное рядом, ghost — третьестепенное. */
  variant?: 'primary' | 'secondary' | 'ghost';
  size?: 'sm' | 'md' | 'lg';
  /** Задан — рендерится как <a> (якорь, tel:), иначе как <button>. */
  href?: string;
  type?: 'button' | 'submit' | 'reset';
  disabled?: boolean;
  onClick?: (e: React.MouseEvent) => void;
  className?: string;
  children?: React.ReactNode;

dtsPropsFor.Card:
/** solid — обычная карточка, interactive — кликабельная (рендерится как <button>, доступна с клавиатуры), dashed — честное пустое состояние. */
  variant?: 'solid' | 'interactive' | 'dashed';
  onClick?: (e: React.MouseEvent) => void;
  className?: string;
  children?: React.ReactNode;

dtsPropsFor.Field:
/** Подпись поля. Оборачивает контрол в <label>, поэтому клик по тексту ставит фокус в поле. */
  label?: string;
  /** Пояснение под полем. */
  hint?: string;
  children?: React.ReactNode;

dtsPropsFor.Input:
type?: string;
  value?: string;
  onChange?: (e: React.ChangeEvent<HTMLInputElement>) => void;
  placeholder?: string;
  required?: boolean;
  disabled?: boolean;
  className?: string;

dtsPropsFor.Select:
value?: string;
  onChange?: (e: React.ChangeEvent<HTMLSelectElement>) => void;
  required?: boolean;
  disabled?: boolean;
  className?: string;
  children?: React.ReactNode;

dtsPropsFor.Textarea:
value?: string;
  onChange?: (e: React.ChangeEvent<HTMLTextAreaElement>) => void;
  placeholder?: string;
  rows?: number;
  required?: boolean;
  className?: string;

dtsPropsFor.Section:
/** Якорь для навигации по странице. */
  id?: string;
  className?: string;
  children?: React.ReactNode;

dtsPropsFor.SectionHeader:
/** Надпись над заголовком — оливковая, единственное регулярное место второго фирменного цвета. */
  eyebrow?: string;
  title?: string;
  description?: string;
  className?: string;

dtsPropsFor.PhotoPlaceholder:
/** Подпись внутри плейсхолдера — что здесь будет за фото. */
  label?: string;
  className?: string;
